export function searchStocks(query: string, limit = 25): PSXStock[] {
  if (!query || !query.trim()) return ALL_PSX_STOCKS.slice(0, limit);
  const q = query.trim().toLowerCase();
  return ALL_PSX_STOCKS.filter(
    (s) =>
      s.symbol.toLowerCase().includes(q) ||
      s.name.toLowerCase().includes(q) ||
      s.sector.toLowerCase().includes(q)
  ).slice(0, limit);
}

export function getStockBySymbol(symbol: string): PSXStock | undefined {
  if (!symbol) return undefined;
  const clean = symbol.trim().toUpperCase();
  return ALL_PSX_STOCKS.find((s) => s.symbol.toUpperCase() === clean);
}

export function getSectorPeers(sector: string, currentSymbol: string, limit = 4): PSXStock[] {
  return ALL_PSX_STOCKS.filter(
    (s) => s.sector.toUpperCase() === sector.toUpperCase() && s.symbol.toUpperCase() !== currentSymbol.toUpperCase()
  ).slice(0, limit);
}
